"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
} from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { OutlineRail } from "@/components/blocks/navigation/OutlineRail"
import type { OutlineRailGroup } from "@/components/blocks/navigation/OutlineRail"
import type { MyCourseOutlineModule } from "@/modules/api/graphql/queries/types/my-course-outline"

/**
 * Filter modules + their lessons by a lower-cased query (module title match keeps
 * all its lessons; otherwise only matching lessons survive). Empty query → unchanged.
 *
 * @param modules - The course's modules.
 * @param query - Lower-cased trimmed search query.
 * @returns The filtered modules.
 */
const filterModules = (
    modules: Array<MyCourseOutlineModule>,
    query: string,
): Array<MyCourseOutlineModule> => {
    if (!query) {
        return modules
    }
    const result: Array<MyCourseOutlineModule> = []
    for (const module of modules) {
        const moduleMatches = module.title.toLowerCase().includes(query)
        const lessons = moduleMatches
            ? module.lessons
            : module.lessons.filter((lesson) => lesson.title.toLowerCase().includes(query))
        if (moduleMatches || lessons.length > 0) {
            result.push({ ...module, lessons })
        }
    }
    return result
}

/**
 * Content-map rail — the lean docs-style course navigation tree shown to the left
 * while reading (module → lesson, read/premium markers, a progress header with a
 * "continue" action). A thin data wrapper: owns the `myCourseOutline` SWR + Redux
 * selection + routing + the controlled search/expand state, and renders the shared
 * {@link OutlineRail} block (which owns the look it shares with the personal-project
 * milestone rail).
 *
 * Positioning (sticky / width / scroll) is owned by the learn shell's
 * {@link FillAvailable} wrapper on desktop and the mobile drawer on small screens.
 */
export const ContentMap = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    const activeContentId = useAppSelector((state) => state.content.id)

    const outlineSwr = useQueryMyCourseOutlineSwr(courseId ?? null)
    const outline = outlineSwr.data

    const [search, setSearch] = useState("")
    const query = search.trim().toLowerCase()
    const modules = useMemo(
        () => (outline ? filterModules(outline.modules, query) : []),
        [outline, query],
    )

    /** Module owning the active lesson — expanded on first paint. */
    const activeModuleId = useMemo(() => {
        if (!outline || !activeContentId) {
            return undefined
        }
        return outline.modules.find((module) =>
            module.lessons.some((lesson) => lesson.id === activeContentId))?.id
    }, [outline, activeContentId])

    /**
     * Expanded modules (controlled) — only the open module shows its read-progress
     * bar; collapsed ones show a compact "n/m" count instead. The active lesson's
     * module auto-opens; a search opens every matching module so hits are visible.
     */
    const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set())
    useEffect(() => {
        if (!activeModuleId) {
            return
        }
        setExpandedKeys((prev) => prev.has(activeModuleId) ? prev : new Set(prev).add(activeModuleId))
    }, [activeModuleId])
    useEffect(() => {
        if (query) {
            setExpandedKeys(new Set(modules.map((module) => module.id)))
        }
    }, [query, modules])

    const progress = outline?.progress
    const currentTask = outline?.currentTask

    /**
     * Route for the "continue" button from `currentTask`. Lessons route straight to
     * their content; challenges route to the owning lesson's challenges tab. Milestone
     * tasks have no rail route yet → null (button hidden).
     */
    const continueHref = useMemo(() => {
        if (!outline || !currentTask || !displayId) {
            return null
        }
        const base = (moduleId: string, contentId: string) =>
            pathConfig().locale(locale).course(displayId).learn().module(moduleId).content(contentId).build()
        if (currentTask.kind === "lesson") {
            const owner = outline.modules.find((module) =>
                module.lessons.some((lesson) => lesson.id === currentTask.id))
            return owner ? base(owner.id, currentTask.id) : null
        }
        if (currentTask.kind === "challenge") {
            for (const module of outline.modules) {
                const lesson = module.lessons.find((item) =>
                    item.challenges.some((challenge) => challenge.id === currentTask.id))
                if (lesson) {
                    return `${base(module.id, lesson.id)}?tab=challenges`
                }
            }
        }
        return null
    }, [outline, currentTask, displayId, locale])

    /** Jump to the viewer's current task. */
    const onContinue = useCallback(() => {
        if (continueHref) {
            router.push(continueHref)
        }
    }, [continueHref, router])

    /** Navigate to the chosen lesson within its module. */
    const onSelectLesson = useCallback(
        (lessonId: string, moduleId: string) => {
            if (!displayId) {
                return
            }
            router.push(
                pathConfig().locale(locale).course(displayId).learn().module(moduleId).content(lessonId).build(),
            )
        },
        [router, locale, displayId],
    )

    /** Navigate to the dedicated module page (title press — caret still toggles). */
    const onOpenModule = useCallback(
        (moduleId: string) => {
            if (!displayId) {
                return
            }
            router.push(
                pathConfig().locale(locale).course(displayId).learn().module(moduleId).build(),
            )
        },
        [router, locale, displayId],
    )

    /** modules → milestone-agnostic rail groups (read markers, minutes meta). */
    const groups = useMemo<Array<OutlineRailGroup>>(
        () => modules.map((module) => {
            const readCount = module.lessons.filter((lesson) => lesson.isRead).length
            return {
                id: module.id,
                title: module.title,
                progress: { done: readCount, total: module.lessons.length },
                collapsedCountLabel: t("courseContents.moduleLessons", {
                    read: readCount,
                    total: module.lessons.length,
                }),
                onTitlePress: () => onOpenModule(module.id),
                items: module.lessons.map((lesson) => ({
                    id: lesson.id,
                    title: lesson.title,
                    isActive: lesson.id === activeContentId,
                    isRead: lesson.isRead,
                    isPremium: lesson.isPremium,
                    meta: (
                        <Typography type="body-xs" color="muted">
                            {t("content.minutesShort", { minutes: lesson.minutesRead })}
                        </Typography>
                    ),
                    onPress: () => onSelectLesson(lesson.id, module.id),
                })),
            }
        }),
        [modules, activeContentId, onSelectLesson, onOpenModule, t],
    )

    return (
        <OutlineRail
            header={progress ? {
                label: t("courseContents.progress"),
                progress: { done: progress.lessonsRead, total: progress.lessonsTotal },
                countLabel: t("courseContents.contentCount", {
                    read: progress.lessonsRead,
                    total: progress.lessonsTotal,
                }),
                // only when you've navigated AWAY from your current task — hide it while
                // you're already reading that task (the button would just point at this page).
                continue: continueHref && currentTask?.id !== activeContentId ? {
                    label: t("courseContents.resume"),
                    onPress: onContinue,
                } : undefined,
            } : undefined}
            search={{
                value: search,
                onChange: setSearch,
                placeholder: t("courseContents.searchPlaceholder"),
                ariaLabel: t("courseContents.searchAria"),
            }}
            groups={groups}
            expandedKeys={expandedKeys}
            onExpandedChange={setExpandedKeys}
            isSkeleton={!outlineSwr.data && !outlineSwr.error}
            async={{
                isEmpty: !outline,
                emptyTitle: t("courseContents.empty"),
                errorTitle: t("courseContents.error"),
                error: !outlineSwr.data ? outlineSwr.error : undefined,
                onRetry: () => { void outlineSwr.mutate() },
                retryLabel: t("courseContents.retry"),
                noMatchLabel: t("courseContents.noMatch"),
            }}
        />
    )
}

export default ContentMap

"use client"

import React from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    LockIcon,
} from "@phosphor-icons/react"
import {
    useRouter,
} from "next/navigation"
import {
    useSidebarNavItems,
} from "@/hooks/useSidebarNavItems"
import type {
    LearnNavBadge,
    LearnNavGroup,
} from "@/components/layouts/LearnShellLayout/types"
import { Chip } from "@/components/atoms/chips/Chip"
import { ResumeRail } from "../ResumeRail"
import { CollapsibleSidebar } from "@/components/blocks/navigation/CollapsibleSidebar"
import { SidebarNavGroup } from "@/components/blocks/navigation/SidebarNavGroup"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { SidebarNavAccordionGroup } from "@/components/blocks/navigation/SidebarNavAccordionGroup"

/** localStorage key persisting the learn course-nav collapsed flag. */
const SIDEBAR_STORAGE_KEY = "starci.learn.sidebar.collapsed"

/**
 * Order the labelled nav clusters render in: the mandatory spine (path), then the
 * aids (practice), then the meta surfaces (track). The first group has no divider;
 * every later group gets a full-width {@link SidebarNavGroup} divider on top.
 */
const GROUP_ORDER: ReadonlyArray<LearnNavGroup> = ["path", "practice", "track"]

/**
 * Render a row's trailing status badge: a warning-tinted due-card count, or the
 * viewer's rank as accent text. Kept small so it doesn't crowd the label.
 *
 * @param badge - The {@link LearnNavBadge} to render.
 * @returns The badge node.
 */
const renderBadge = (badge: LearnNavBadge): React.ReactNode => {
    if (badge.tone === "rank") {
        return (
            <Typography type="body-xs" className="text-accent-soft-foreground">
                {`#${badge.value}`}
            </Typography>
        )
    }
    return (
        <Chip tone="warning" text={String(badge.value)} />
    )
}

/** Props for {@link LearnSidebar}. */
export type LearnSidebarProps = Record<string, never>
/**
 * Course-learn left navigation rail (desktop).
 *
 * Container: pulls the shared nav entries from {@link useSidebarNavItems} and
 * composes the {@link CollapsibleSidebar} block — which owns the collapse-in-place
 * animation, the toggle, the divider, and persisting the collapsed flag. Rows are
 * split into separator-divided clusters by their `group` (study / practice);
 * each row is a {@link SidebarNavItem} that self-dispatches its tab + navigation
 * through the shared select handler. Hidden below `lg` (mobile uses the drawer in
 * {@link import("../LearnMobileBar").LearnMobileBar}). `"use client"` for the hooks.
 *
 * @param props - {@link LearnSidebarProps}
 */
export const LearnSidebar = () => {
    const t = useTranslations()
    const router = useRouter()
    // shared entries + active tab (also used by the mobile drawer)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // role-group captions (sentence case — no uppercase)
    const groupLabels: Record<LearnNavGroup, string> = {
        path: t("nav.groupPath"),
        practice: t("nav.groupPractice"),
        track: t("nav.groupTrack"),
    }
    return (
        <CollapsibleSidebar
            title={t("nav.courseMenu")}
            collapseLabel={t("nav.collapseLeftRail")}
            expandLabel={t("nav.expandLeftRail")}
            storageKey={SIDEBAR_STORAGE_KEY}
            topSlot={<ResumeRail />}
        >
            {GROUP_ORDER.map((group, index) => {
                // rows belonging to this cluster, in their declared order
                const groupItems = items.filter((item) => item.group === group)
                if (groupItems.length === 0) {
                    return null
                }
                return (
                    // first cluster has no divider; later clusters get the full-width separator
                    <SidebarNavGroup key={group} divider={index > 0} label={groupLabels[group]}>
                        {groupItems.map((item) => (
                            item.children ? (
                                <SidebarNavAccordionGroup
                                    key={item.value}
                                    icon={item.icon}
                                    label={item.label}
                                    items={item.children.map((child) => ({
                                        value: child.value,
                                        label: child.label,
                                        isActive: child.isActive,
                                        onPress: () => router.push(child.url),
                                    }))}
                                />
                            ) : (
                                <SidebarNavItem
                                    key={item.value}
                                    icon={<item.icon className="size-5 shrink-0" />}
                                    label={item.label}
                                    isActive={selectedTab === item.tab}
                                    endContent={item.locked ? (
                                        <LockIcon
                                            aria-label={t("enrollGate.locked")}
                                            focusable="false"
                                            className="size-4 text-muted"
                                        />
                                    ) : item.badge ? renderBadge(item.badge) : undefined}
                                    onPress={() => onSelect(item)}
                                />
                            )
                        ))}
                    </SidebarNavGroup>
                )
            })}
        </CollapsibleSidebar>
    )
}

"use client"

import React, { useEffect, useRef, useState } from "react"
import { Button, ListBox, Typography, cn } from "@heroui/react"
import {
    AnimatePresence,
    motion,
    useMotionValueEvent,
    useReducedMotion,
    useScroll,
} from "framer-motion"
import { useTranslations } from "next-intl"
import {
    ArrowRightIcon,
    ArrowUpIcon,
    BookOpenIcon,
    CheckCircleIcon,
    PlayCircleIcon,
    RobotIcon,
    RocketLaunchIcon,
    TrophyIcon,
    WarningCircleIcon,
} from "@phosphor-icons/react"
import { GithubIcon } from "@/components/svg/GithubIcon"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { LANDING_LOOP_STEPS } from "@/modules/utils/landing-constants"
import { SectionHeading } from "@/components/blocks/marketing/SectionHeading"
import { ShowcaseMockup, SHOWCASE_THEMES } from "@/components/blocks/marketing/ShowcaseMockup"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link LearnLoopScroll}. */
export type LearnLoopScrollProps = WithClassNames<undefined>

/** Icon for each step of the learning loop (keys match `landing.learnLoop.items.{key}`). */
const STEP_ICONS: Record<string, React.ReactNode> = {
    read: <BookOpenIcon aria-hidden focusable="false" />,
    grade: <RobotIcon aria-hidden focusable="false" />,
    capstone: <RocketLaunchIcon aria-hidden focusable="false" />,
    rank: <TrophyIcon aria-hidden focusable="false" />,
}

/** Address bar for each panel (reads like a real screen of the product). */
const STEP_URL: Record<string, string> = {
    read: "starci.academy/learn/dead-letter-queue",
    grade: "starci.academy/submit",
    capstone: "starci.academy/capstone/the-shop",
    rank: "starci.academy/leaderboard",
}

/**
 * Sample lesson illustrating the "Read" step — the SAME lesson (Dead Letter Queue) written in 4 languages.
 * Each tab swaps the filename + code; click to switch. The code is deliberately more than 1 line deep, for realism.
 */
const READ_LESSON = [
    {
        label: "TS",
        file: "order-consumer.ts",
        code: `// retry; past the threshold → DLQ
async function onMessage(msg: Message) {
  try { await handle(msg); await msg.ack() }
  catch {
    if (msg.attempts >= MAX) await dlq.send(msg.body)
    else await msg.nack()
  }
}`,
    },
    {
        label: "Java",
        file: "OrderConsumer.java",
        code: `// retry; past the threshold → DLQ
void onMessage(Message msg) {
  try { handle(msg); msg.ack(); }
  catch (Exception e) {
    if (msg.attempts() >= MAX) dlq.send(msg.body());
    else msg.nack();
  }
}`,
    },
    {
        label: "C#",
        file: "OrderConsumer.cs",
        code: `// retry; past the threshold → DLQ
async Task OnMessage(Message msg) {
  try { await Handle(msg); await msg.AckAsync(); }
  catch (Exception e) {
    if (msg.Attempts >= Max) await dlq.SendAsync(msg.Body);
    else await msg.NackAsync();
  }
}`,
    },
    {
        label: "Go",
        file: "consumer.go",
        code: `func onMessage(msg Message) {
  err := handle(msg)
  if err == nil { msg.Ack(); return }
  if msg.Attempts >= Max { dlq.Send(msg.Body) } else { msg.Nack() }
}`,
    },
] as const

/** Token for code tinting (comment · string · keyword) — enough for the demo, not a full lexer. */
const CODE_TOKEN = /(\/\/[^\n]*)|("(?:[^"\\]|\\.)*")|\b(const|let|var|async|await|function|func|return|if|else|for|class|public|private|static|void|new|using|namespace|package|import|from|type|struct|interface|defer|throw|catch|try|final|int|Task|Exception|nil|err)\b/g

/** Colors one line of code: comment → muted · string → warning · keyword → accent. */
const tintLine = (line: string): React.ReactNode => {
    if (line === "") {
        return " "
    }
    const out: React.ReactNode[] = []
    let last = 0
    let key = 0
    let match: RegExpExecArray | null
    CODE_TOKEN.lastIndex = 0
    while ((match = CODE_TOKEN.exec(line)) !== null) {
        if (match.index > last) {
            out.push(line.slice(last, match.index))
        }
        const token = match[0]
        const cls = match[1] ? "text-muted" : match[2] ? "text-warning-soft-foreground" : "text-accent-soft-foreground"
        out.push(<span key={key++} className={cls}>{token}</span>)
        last = match.index + token.length
    }
    if (last < line.length) {
        out.push(line.slice(last))
    }
    return out
}

/** Code block with line numbers + tint (mono). */
const CodeBlock = ({ code }: { code: string }) => {
    const lines = code.split("\n")
    return (
        <div className="flex font-mono text-xs leading-relaxed">
            <div aria-hidden data-principle="sibling-stack" className="flex flex-col items-end gap-2 border-r border-default/70 px-3 py-4 text-muted/60 select-none">
                {lines.map((_, index) => <span key={index}>{index + 1}</span>)}
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2 overflow-x-auto px-4 py-4">
                {lines.map((line, index) => <span key={index} className="whitespace-pre">{tintLine(line)}</span>)}
            </div>
        </div>
    )
}

/** Sample leaderboard (marketing, not real data). */
const RANK_ROWS = [
    { rank: 1, name: "minh.dev", xp: 4280 },
    { rank: 2, name: "huyen.codes", xp: 2715 },
    { rank: 3, name: "thanh.io", xp: 1940 },
] as const

/**
 * The right-column visual changes per step — flat, built from tokens (no real images), each panel
 * anchored by the step's icon. Four panels: Read (4-language tabs + code tint) · AI Grading (score
 * ring + pass/warn criteria) · Capstone (mini architecture diagram) · Leaderboard (medal +
 * avatar + XP bar + a "You" row). Elements inside each panel enter with a light stagger.
 */
const StepVisual = ({ stepKey }: { stepKey: string }) => {
    const t = useTranslations()
    const reduce = useReducedMotion()
    // the currently selected language in the "Read" step (clickable tab; resets when the panel re-mounts)
    const [readLang, setReadLang] = useState(0)

    const childVariants = reduce
        ? { hidden: { opacity: 1 }, show: { opacity: 1 } }
        : { hidden: { opacity: 0, y: 8 }, show: { opacity: 1, y: 0 } }
    const stagger = {
        hidden: {},
        show: { transition: { staggerChildren: reduce ? 0 : 0.07, delayChildren: reduce ? 0 : 0.05 } },
    }

    // The right panel = a LabeledCard block (label OUTSIDE: step icon + title · tag on the right). Body
    // = the step's visual + one line of description (each card "says" a bit more, not a bare visual). Light stagger.
    const shell = (children: React.ReactNode, align: "center" | "start" = "center") => (
        <ShowcaseMockup
            url={STEP_URL[stepKey]}
            aspect="video"
            tilt="left"
            backdrop="glow"
            theme={SHOWCASE_THEMES.starci}
            contentClassName={cn("flex flex-col p-4", align === "start" ? "justify-start" : "justify-center")}
        >
            <motion.div
                variants={stagger}
                initial="hidden"
                animate="show"
                className="flex flex-col gap-3" data-principle="content-row"
            >
                {children}
            </motion.div>
        </ShowcaseMockup>
    )

    if (stepKey === "read") {
        return shell(
            <>
                <motion.div variants={childVariants} data-principle="group-boundary" className="flex flex-wrap gap-4 border-b border-default text-xs">
                    {READ_LESSON.map((item, index) => (
                        <button
                            key={item.label}
                            type="button"
                            onClick={() => setReadLang(index)}
                            aria-pressed={index === readLang}
                            className={cn(
                                "-mb-px cursor-pointer border-b-2 pb-2 transition-colors",
                                index === readLang
                                    ? "border-accent font-medium text-accent-soft-foreground"
                                    : "border-transparent text-muted hover:text-foreground",
                            )}
                        >
                            {item.label}
                        </button>
                    ))}
                </motion.div>
                <motion.div variants={childVariants} className="overflow-hidden rounded-xl border border-default bg-default">
                    <Box principle="control-pad" className="border-b border-default/70">
                        <span className="font-mono text-xs text-muted">{READ_LESSON[readLang].file}</span>
                    </Box>
                    <CodeBlock code={READ_LESSON[readLang].code} />
                </motion.div>
            </>,
            "start",
        )
    }

    if (stepKey === "grade") {
        const criteria = [
            { ok: true, text: "Idempotency key handled correctly.", pts: "+30" },
            { ok: true, text: "Sensible retry + backoff.", pts: "+25" },
            { ok: false, text: "Missing rate-limit at the gateway.", pts: "−8" },
        ]
        return shell(
            <>
                {/* verdict = HeroUI Alert style (matches SubmissionResult): success tint + icon + score */}
                <motion.div variants={childVariants} data-principle="content-row" className="flex items-center gap-3 rounded-xl bg-success-soft px-3 py-2">
                    <CheckCircleIcon aria-hidden focusable="false" className="size-7 shrink-0 text-success-soft-foreground" />
                    <div className="flex flex-1 flex-col">
                        <span className="text-sm font-semibold text-success-soft-foreground">{t("submissionResult.passed")} · 92/100</span>
                        <span className="text-xs text-success-soft-foreground/80">need ≥ 70 to pass</span>
                    </div>
                    <span data-principle="control-pad" className="shrink-0 rounded-full bg-success/15 px-3 py-1 text-xs font-medium text-success-soft-foreground">+120 XP</span>
                </motion.div>
                <motion.div variants={childVariants} data-principle="sibling-stack" className="flex flex-col gap-2">
                    {criteria.map((item) => (
                        <span key={item.text} data-principle="icon-text" className="flex items-center gap-2 text-sm text-muted">
                            {item.ok ? (
                                <CheckCircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-success-soft-foreground" />
                            ) : (
                                <WarningCircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-warning-soft-foreground" />
                            )}
                            <span className="flex-1">{item.text}</span>
                            <span className={cn("shrink-0 font-medium", item.ok ? "text-success-soft-foreground" : "text-warning-soft-foreground")}>{item.pts}</span>
                        </span>
                    ))}
                </motion.div>
            </>,
        )
    }

    if (stepKey === "capstone") {
        const milestones = [
            { label: "Scaffold & CI", state: "done" },
            { label: "Auth + API Gateway", state: "done" },
            { label: "Split services · DB-per-service", state: "active" },
        ] as const
        return shell(
            <>
                <motion.div variants={childVariants} className="flex items-center justify-between">
                    <span className="font-mono text-sm font-medium">the-shop</span>
                    <span className="flex items-center gap-2 text-xs text-muted" data-principle="icon-text">
                        <GithubIcon className="size-3.5" />
                        main
                    </span>
                </motion.div>
                <motion.div variants={childVariants} data-principle="sibling-stack" className="flex flex-col gap-2">
                    <div className="flex items-center justify-between text-xs text-muted">
                        <span>Progress</span>
                        <span>8/20 milestones · 40%</span>
                    </div>
